-- 033_seed_topup_packages.sql
-- Ensure standard top-up packages exist for mobile/web purchasing

CREATE TABLE IF NOT EXISTS "topup_packages" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "package_name" varchar(100) NOT NULL,
  "price_vnd" decimal(12,2) NOT NULL,
  "credit_amount" int NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true
);

INSERT INTO "topup_packages" ("id", "package_name", "price_vnd", "credit_amount", "is_active")
VALUES
  (1, 'Gói Khởi đầu (Starter)', 50000.00, 100, true),
  (2, 'Gói Tiêu chuẩn (Standard)', 100000.00, 500, true),
  (3, 'Gói Chuyên nghiệp (Pro)', 200000.00, 1000, true),
  (4, 'Gói Doanh nghiệp (Enterprise)', 500000.00, 5000, true)
ON CONFLICT ("id") DO UPDATE SET
  "package_name" = EXCLUDED."package_name",
  "price_vnd" = EXCLUDED."price_vnd",
  "credit_amount" = EXCLUDED."credit_amount",
  "is_active" = true;

DO $$
DECLARE
  seq text;
BEGIN
  seq := pg_get_serial_sequence('topup_packages', 'id');
  IF seq IS NOT NULL THEN
    EXECUTE 'SELECT setval(' || quote_literal(seq) || ', COALESCE((SELECT MAX(id) FROM "topup_packages"), 1))';
  END IF;
END $$;
